INSERT INTO `datenbank_texte` (`Formular`, `Textfeld`, `de`, `gb`, `fr`, `la`) VALUES ('login', 'PasswortNeuSetzen', 'Die Sicherheit der Datenbank wurde verbessert. Das Passwort muss neu gesetzt werden.', 'The security of the database has been improved. The password must be reset.', 'La sécurité de la base de données a été améliorée. Le mot de passe doit être réinitialisé.', 'Securitas datorum repositorii melior facta est. Tessera nova constituenda est.');

