INSERT INTO `datenbank_texte` (`Formular`, `Textfeld`, `de`, `gb`, `fr`, `la`) VALUES ('login', 'EingabeEmail', '1. Geben Sie unten Ihre E-Mail Adresse ein.', '1. Enter your email address below.', '1. Entrez votre adresse e-mail ci-dessous.', '1. Inscribe infra inscriptionem electronicam tuam.');

INSERT INTO `datenbank_texte` (`Formular`, `Textfeld`, `de`, `gb`, `fr`, `la`) VALUES ('login', 'SendetEmail', '2. Unser System sendet Ihnen einen Link an Ihre E-Mail Adresse.', '2. Our system will send you a link to your email address.', '2. Notre système vous enverra un lien à votre adresse e-mail.', '2. Systema nostrum tibi vinculum ad inscriptionem electronicam tuam mittet.');

INSERT INTO `datenbank_texte` (`Formular`, `Textfeld`, `de`, `gb`, `fr`, `la`) VALUES ('login', 'KlickLink', '3. Klicken Sie den Link in Ihrer E-mail an, sie werden weiter geleitet um Ihr Passwort neu zu setzen.', '3. Click the link in your email, and you will be redirected to reset your password.', '3. Cliquez sur le lien dans votre e-mail, vous serez redirigé pour réinitialiser votre mot de passe.', '3. Preme vinculum in epistula tua electronica, et ad tesserae restitutionem redirectus eris.');

